import UIKit
import SpriteKit
import GameKit

final class GameViewController: UIViewController, GameSceneDelegate {
    private let spriteView = SKView()
    private let scoreLabel = UILabel()
    private let progressLabel = UILabel()
    private let livesLabel = UILabel()
    private let energy = UIProgressView(progressViewStyle: .bar)
    private let musicButton = UIButton(type: .system)
    private let fruitInfoButton = UIButton(type: .system)
    private let questionService = QuestionService()
    private var progress = ProgressStore.shared.load()
    private var gameScene: GameScene?
    private var currentExam: [ClinicalQuestion] = []
    private var currentExamKind: ExamKind = .rescue
    private var questionIndex = 0
    private var correctCount = 0
    private var selectedAnswer: String?
    private var lastReportedInfiniteScore = 0
    private var fruitInfoOpenedFromGame = false
    private let overlay = UIView()
    private let panel = UIStackView()
    private let menuArtwork = UIImageView()
    private var menuActionButtons: [UIButton] = []

    override func viewDidLoad() { super.viewDidLoad(); configureView(); NotificationCenter.default.addObserver(self, selector: #selector(pauseForBackground), name: UIApplication.willResignActiveNotification, object: nil); NotificationCenter.default.addObserver(self, selector: #selector(resumeFromBackground), name: UIApplication.didBecomeActiveNotification, object: nil); authenticateGameCenter(); showHome() }
    override var supportedInterfaceOrientations: UIInterfaceOrientationMask { .portrait }
    override func viewWillDisappear(_ animated: Bool) { super.viewWillDisappear(animated); gameScene?.setPaused(true) }
    override func viewDidAppear(_ animated: Bool) { super.viewDidAppear(animated); if overlay.isHidden { gameScene?.setPaused(false) } }
    @objc private func pauseForBackground() { gameScene?.setPaused(true); ChiptunePlayer.shared.pause() }
    @objc private func resumeFromBackground() { if overlay.isHidden { gameScene?.setPaused(false); ChiptunePlayer.shared.resume() } }

    private func configureView() {
        view.backgroundColor = .black; spriteView.translatesAutoresizingMaskIntoConstraints = false; view.addSubview(spriteView); NSLayoutConstraint.activate([spriteView.leadingAnchor.constraint(equalTo: view.leadingAnchor), spriteView.trailingAnchor.constraint(equalTo: view.trailingAnchor), spriteView.topAnchor.constraint(equalTo: view.topAnchor), spriteView.bottomAnchor.constraint(equalTo: view.bottomAnchor)])
        let hud = UIStackView(); hud.axis = .horizontal; hud.distribution = .equalSpacing; hud.alignment = .top; hud.translatesAutoresizingMaskIntoConstraints = false; hud.isUserInteractionEnabled = false
        for label in [scoreLabel, progressLabel, livesLabel] { label.font = .monospacedDigitSystemFont(ofSize: 16, weight: .bold); label.textColor = .white; label.backgroundColor = UIColor.black.withAlphaComponent(0.38); label.layer.cornerRadius = 10; label.clipsToBounds = true; label.textAlignment = .center; label.widthAnchor.constraint(greaterThanOrEqualToConstant: 88).isActive = true; label.heightAnchor.constraint(equalToConstant: 36).isActive = true }
        hud.addArrangedSubview(scoreLabel); hud.addArrangedSubview(progressLabel); hud.addArrangedSubview(livesLabel); view.addSubview(hud); NSLayoutConstraint.activate([hud.leadingAnchor.constraint(equalTo: view.safeAreaLayoutGuide.leadingAnchor, constant: 14), hud.trailingAnchor.constraint(equalTo: view.safeAreaLayoutGuide.trailingAnchor, constant: -14), hud.topAnchor.constraint(equalTo: view.safeAreaLayoutGuide.topAnchor, constant: 12)])
        musicButton.translatesAutoresizingMaskIntoConstraints = false; musicButton.titleLabel?.font = .systemFont(ofSize: 21, weight: .bold); musicButton.tintColor = .white; musicButton.backgroundColor = UIColor.black.withAlphaComponent(0.42); musicButton.layer.cornerRadius = 18; musicButton.addTarget(self, action: #selector(toggleMusic), for: .touchUpInside); view.addSubview(musicButton); NSLayoutConstraint.activate([musicButton.trailingAnchor.constraint(equalTo: view.safeAreaLayoutGuide.trailingAnchor, constant: -14), musicButton.topAnchor.constraint(equalTo: hud.bottomAnchor, constant: 10), musicButton.widthAnchor.constraint(equalToConstant: 44), musicButton.heightAnchor.constraint(equalToConstant: 36)]); updateMusicButton()
        fruitInfoButton.translatesAutoresizingMaskIntoConstraints = false; fruitInfoButton.setTitle("ⓘ", for: .normal); fruitInfoButton.titleLabel?.font = .systemFont(ofSize: 23, weight: .bold); fruitInfoButton.tintColor = .white; fruitInfoButton.backgroundColor = UIColor.black.withAlphaComponent(0.42); fruitInfoButton.layer.cornerRadius = 18; fruitInfoButton.accessibilityLabel = "Información sobre las frutas"; fruitInfoButton.addTarget(self, action: #selector(showFruitInformation), for: .touchUpInside); view.addSubview(fruitInfoButton); NSLayoutConstraint.activate([fruitInfoButton.trailingAnchor.constraint(equalTo: musicButton.trailingAnchor), fruitInfoButton.topAnchor.constraint(equalTo: musicButton.bottomAnchor, constant: 8), fruitInfoButton.widthAnchor.constraint(equalToConstant: 44), fruitInfoButton.heightAnchor.constraint(equalToConstant: 36)])
        energy.translatesAutoresizingMaskIntoConstraints = false; energy.tintColor = .systemCyan; energy.trackTintColor = UIColor.white.withAlphaComponent(0.25); view.addSubview(energy); NSLayoutConstraint.activate([energy.leadingAnchor.constraint(equalTo: view.safeAreaLayoutGuide.leadingAnchor, constant: 28), energy.trailingAnchor.constraint(equalTo: view.safeAreaLayoutGuide.trailingAnchor, constant: -28), energy.bottomAnchor.constraint(equalTo: view.safeAreaLayoutGuide.bottomAnchor, constant: -22)])
        overlay.translatesAutoresizingMaskIntoConstraints = false; overlay.backgroundColor = UIColor.black.withAlphaComponent(0.62); view.addSubview(overlay); NSLayoutConstraint.activate([overlay.leadingAnchor.constraint(equalTo: view.leadingAnchor), overlay.trailingAnchor.constraint(equalTo: view.trailingAnchor), overlay.topAnchor.constraint(equalTo: view.topAnchor), overlay.bottomAnchor.constraint(equalTo: view.bottomAnchor)])
        menuArtwork.translatesAutoresizingMaskIntoConstraints = false; menuArtwork.contentMode = .scaleAspectFill; menuArtwork.clipsToBounds = true; menuArtwork.isHidden = true; overlay.addSubview(menuArtwork); NSLayoutConstraint.activate([menuArtwork.leadingAnchor.constraint(equalTo: overlay.leadingAnchor), menuArtwork.trailingAnchor.constraint(equalTo: overlay.trailingAnchor), menuArtwork.topAnchor.constraint(equalTo: overlay.topAnchor), menuArtwork.bottomAnchor.constraint(equalTo: overlay.bottomAnchor)])
        panel.axis = .vertical; panel.spacing = 12; panel.alignment = .fill; panel.translatesAutoresizingMaskIntoConstraints = false; panel.backgroundColor = UIColor(red: 0.06, green: 0.10, blue: 0.19, alpha: 0.98); panel.layer.cornerRadius = 24; panel.layoutMargins = UIEdgeInsets(top: 24, left: 20, bottom: 24, right: 20); panel.isLayoutMarginsRelativeArrangement = true; overlay.addSubview(panel); NSLayoutConstraint.activate([panel.centerYAnchor.constraint(equalTo: overlay.centerYAnchor), panel.leadingAnchor.constraint(equalTo: overlay.leadingAnchor, constant: 22), panel.trailingAnchor.constraint(equalTo: overlay.trailingAnchor, constant: -22), panel.heightAnchor.constraint(lessThanOrEqualTo: overlay.heightAnchor, multiplier: 0.86)])
    }

    private func showHome() { ChiptunePlayer.shared.playMenu(); clearPanel(); showMenuArtwork(named: "home-menu"); addArtworkButton(label: "Jugar nivel \(progress.unlockedLevel)", x: 0.10, y: 0.51, width: 0.80, height: 0.10, action: #selector(startSelectedLevel)); addArtworkButton(label: "Elegir personaje", x: 0.10, y: 0.63, width: 0.80, height: 0.10, action: #selector(showCharacterSelection)); addArtworkButton(label: "Estadísticas clínicas", x: 0.10, y: 0.74, width: 0.80, height: 0.10, action: #selector(showStatistics)); addArtworkButton(label: progress.hasCompletedAllLevels ? "Modo infinito" : "Modo infinito bloqueado", x: 0.10, y: 0.85, width: 0.80, height: 0.11, action: progress.hasCompletedAllLevels ? #selector(startInfinite) : #selector(showInfiniteLocked)); overlay.isHidden = false }
    private var characterName: String { ["Naranja", "Azul", "Amarillo", "Verde"][progress.selectedCharacter] }
    @objc private func showCharacterSelection() { clearPanel(); showMenuArtwork(named: "character-menu"); addArtworkButton(label: "Personaje naranja", x: 0.06, y: 0.35, width: 0.43, height: 0.22, tag: 0, action: #selector(selectCharacter(_:))); addArtworkButton(label: "Personaje azul", x: 0.51, y: 0.35, width: 0.43, height: 0.22, tag: 1, action: #selector(selectCharacter(_:))); addArtworkButton(label: "Personaje amarillo", x: 0.06, y: 0.59, width: 0.43, height: 0.22, tag: 2, action: #selector(selectCharacter(_:))); addArtworkButton(label: "Personaje verde", x: 0.51, y: 0.59, width: 0.43, height: 0.22, tag: 3, action: #selector(selectCharacter(_:))); addArtworkButton(label: "Volver al inicio", x: 0.10, y: 0.85, width: 0.80, height: 0.10, action: #selector(showHomeAction)); overlay.isHidden = false }
    @objc private func selectCharacter(_ sender: UIButton) { progress.selectedCharacter = sender.tag; ProgressStore.shared.save(progress); showCharacterSelection() }
    @objc private func startSelectedLevel() { start(level: progress.unlockedLevel, infinite: false) }
    @objc private func startInfinite() { guard progress.hasCompletedAllLevels else { showInfiniteLocked(); return }; start(level: 5, infinite: true) }
    @objc private func showInfiniteLocked() { clearPanel(); addTitle("Modo infinito bloqueado", subtitle: "Supera los cinco niveles y sus exámenes finales para desbloquearlo."); addButton("Volver", action: #selector(showHomeAction)); overlay.isHidden = false }
    private func start(level: Int, infinite: Bool) { let scene = GameScene(size: spriteView.bounds.size); scene.scaleMode = .resizeFill; scene.gameDelegate = self; gameScene = scene; spriteView.presentScene(scene); scene.begin(level: level, progress: progress, infinite: infinite); ChiptunePlayer.shared.updateGameMusic(level: level, platform: scene.platformIndex, infinite: infinite); overlay.isHidden = true }

    private func addTitle(_ title: String, subtitle: String) { let titleLabel = UILabel(); titleLabel.text = title; titleLabel.font = .systemFont(ofSize: 30, weight: .heavy); titleLabel.textColor = .systemYellow; titleLabel.textAlignment = .center; panel.addArrangedSubview(titleLabel); let subtitleLabel = UILabel(); subtitleLabel.text = subtitle; subtitleLabel.font = .systemFont(ofSize: 15, weight: .medium); subtitleLabel.textColor = .white; subtitleLabel.numberOfLines = 0; subtitleLabel.textAlignment = .center; panel.addArrangedSubview(subtitleLabel) }
    private func addFootnote(_ text: String) { let label = UILabel(); label.text = text; label.textColor = .lightGray; label.numberOfLines = 0; label.font = .systemFont(ofSize: 12); label.textAlignment = .center; panel.addArrangedSubview(label) }
    private func addButton(_ title: String, action: Selector) { let button = UIButton(type: .system); button.setTitle(title, for: .normal); button.titleLabel?.font = .systemFont(ofSize: 17, weight: .bold); button.setTitleColor(.black, for: .normal); button.backgroundColor = .systemYellow; button.layer.cornerRadius = 13; button.heightAnchor.constraint(equalToConstant: 50).isActive = true; button.addTarget(self, action: action, for: .touchUpInside); panel.addArrangedSubview(button) }
    private func clearPanel() { panel.arrangedSubviews.forEach { $0.removeFromSuperview() }; menuActionButtons.forEach { $0.removeFromSuperview() }; menuActionButtons.removeAll(); menuArtwork.isHidden = true; panel.isHidden = false; overlay.backgroundColor = UIColor.black.withAlphaComponent(0.62) }

    func gameScene(_ scene: GameScene, didUpdateHUD score: Int, platform: Int, lives: Int, level: Int, energy: CGFloat) { scoreLabel.text = "⭐ \(score)"; progressLabel.text = scene.isInfinite ? "∞ \(platform)" : "\(platform)/100"; livesLabel.text = "🍎 \(max(lives, 0))"; self.energy.progress = Float(energy); ChiptunePlayer.shared.updateGameMusic(level: level, platform: platform, infinite: scene.isInfinite); if scene.isInfinite && score >= lastReportedInfiniteScore + 10 { lastReportedInfiniteScore = score; reportScore(score, leaderboard: "vet_jump_infinite_score") }; scene.snapshot(into: &progress); ProgressStore.shared.save(progress) }
    func gameScene(_ scene: GameScene, requestExam kind: ExamKind) { ChiptunePlayer.shared.stopForQuestion(); currentExamKind = kind; currentExam = questionService.exam(kind: kind, level: scene.level, excluding: progress.answeredQuestionIDs); questionIndex = 0; correctCount = 0; selectedAnswer = nil; presentQuestion() }
    func gameSceneDidFinishLevel(_ scene: GameScene) { ChiptunePlayer.shared.stopForQuestion(); currentExamKind = .final; currentExam = questionService.exam(kind: .final, level: scene.level, excluding: progress.answeredQuestionIDs); questionIndex = 0; correctCount = 0; presentQuestion() }
    func gameSceneDidEndGame(_ scene: GameScene) { showEndGame("Fin de partida", detail: "No has superado el examen. Puedes intentarlo de nuevo desde la plataforma 0 del nivel.") }

    private func presentQuestion() { guard questionIndex < currentExam.count else { finishExam(); return }; clearPanel(); overlay.isHidden = false; let question = currentExam[questionIndex]; addQuestionProgress(); let stem = UILabel(); stem.text = question.enunciado; stem.numberOfLines = 0; stem.textColor = .white; stem.font = .systemFont(ofSize: 19, weight: .bold); stem.textAlignment = .center; panel.addArrangedSubview(stem); for key in ["A", "B", "C", "D"] { guard let option = question.opciones[key] else { continue }; let button = UIButton(type: .system); var configuration = UIButton.Configuration.plain(); configuration.contentInsets = NSDirectionalEdgeInsets(top: 13, leading: 14, bottom: 13, trailing: 14); button.configuration = configuration; button.setTitle("\(key). \(option)", for: .normal); button.titleLabel?.font = .systemFont(ofSize: 16, weight: .semibold); button.titleLabel?.numberOfLines = 0; button.contentHorizontalAlignment = .left; button.setTitleColor(.white, for: .normal); button.backgroundColor = UIColor(red: 0.12, green: 0.10, blue: 0.28, alpha: 0.96); button.layer.cornerRadius = 14; button.layer.borderWidth = 1.5; button.layer.borderColor = UIColor.systemPurple.withAlphaComponent(0.85).cgColor; button.accessibilityIdentifier = key; button.addTarget(self, action: #selector(answerSelected(_:)), for: .touchUpInside); panel.addArrangedSubview(button) } }
    @objc private func answerSelected(_ sender: UIButton) { guard let answer = sender.accessibilityIdentifier, questionIndex < currentExam.count else { return }; let question = currentExam[questionIndex]; let correct = answer == question.respuestaCorrecta; if correct { correctCount += 1 }; progress.answeredQuestionIDs.insert(question.id); var stat = progress.subjectStats[question.area] ?? SubjectStat(); stat.total += 1; if correct { stat.correct += 1 }; progress.subjectStats[question.area] = stat; ProgressStore.shared.save(progress); clearPanel(); addTitle(correct ? "¡Correcto!" : "Respuesta incorrecta", subtitle: "Respuesta: \(question.respuestaCorrecta) · \(correctCount) aciertos"); let explanation = UILabel(); explanation.text = question.explicacion.porQueCorrecta; explanation.numberOfLines = 0; explanation.textColor = .white; explanation.font = .systemFont(ofSize: 14); panel.addArrangedSubview(explanation); addButton("Continuar", action: #selector(nextQuestion)) }
    @objc private func nextQuestion() { questionIndex += 1; presentQuestion() }
    private func finishExam() { let success = correctCount >= currentExamKind.requiredCorrect; clearPanel(); addTitle(success ? "¡Examen superado!" : "Examen no superado", subtitle: "\(correctCount)/\(currentExam.count) aciertos · se necesitan \(currentExamKind.requiredCorrect)"); if success, currentExamKind == .final { let completedLevel = gameScene?.level ?? 1; progress.completedLevel = max(progress.completedLevel, completedLevel); progress.unlockedLevel = min(5, max(progress.unlockedLevel, completedLevel + 1)); progress.platform = 0; progress.score = 0; progress.lives = 1; ProgressStore.shared.save(progress); if progress.hasCompletedAllLevels { addButton("Modo infinito desbloqueado ♾️", action: #selector(startInfinite)) } else { addButton("Siguiente nivel", action: #selector(continueAfterFinal)) } } else { addButton(success ? "Continuar jugando" : "Aceptar", action: #selector(continueAfterExam)) }; overlay.isHidden = false }
    @objc private func continueAfterFinal() { guard let gameScene else { return }; reportScore(gameScene.score, leaderboard: "vet_jump_total_score"); start(level: min(gameScene.level + 1, 5), infinite: false) }
    @objc private func continueAfterExam() { let wasSuccessful = correctCount >= currentExamKind.requiredCorrect; overlay.isHidden = true; gameScene?.resumeAfterExam(success: wasSuccessful, kind: currentExamKind); if gameScene?.isGameOver == true { return }; if wasSuccessful { ChiptunePlayer.shared.resumeAfterQuestion() }; if !wasSuccessful && currentExamKind != .final && gameScene?.pendingFruit == nil { showHome() } }
    private func showEndGame(_ title: String, detail: String) { clearPanel(); addTitle(title, subtitle: detail); addButton("Volver al inicio", action: #selector(showHomeAction)); overlay.isHidden = false }
    @objc private func showHomeAction() { showHome() }
    @objc private func showFruitInformation() { fruitInfoOpenedFromGame = overlay.isHidden; if fruitInfoOpenedFromGame { gameScene?.setPaused(true); ChiptunePlayer.shared.pause() }; clearPanel(); addTitle("FRUTAS ESPECIALES", subtitle: "Cada fruta puede cambiar tu partida"); addFootnote("🍎 Manzana: +1 vida inmediata."); addFootnote("🍌 Plátano: aprueba el rescate y gana +1 vida."); addFootnote("🍇 Uvas: aprueba y avanza 3 plataformas; si fallas retrocedes 5."); addFootnote("🍋 Limón: si suspendes el rescate, termina la partida."); addFootnote("Rescates de fruta: 10 preguntas; necesitas 7 aciertos."); addFootnote("🥦 Brócoli: examen de 10 preguntas; necesitas 8 aciertos."); addButton(fruitInfoOpenedFromGame ? "Continuar" : "Volver", action: #selector(closeFruitInformation)); overlay.isHidden = false }
    @objc private func closeFruitInformation() { if fruitInfoOpenedFromGame { fruitInfoOpenedFromGame = false; overlay.isHidden = true; gameScene?.setPaused(false); ChiptunePlayer.shared.resume() } else { showHome() } }
    @objc private func toggleMusic() { _ = ChiptunePlayer.shared.toggleMuted(); updateMusicButton() }
    private func updateMusicButton() { musicButton.setTitle(ChiptunePlayer.shared.isMuted ? "🔇" : "🔊", for: .normal) }
    private func addQuestionProgress() { let label = UILabel(); label.text = "Pregunta \(questionIndex + 1)/\(currentExam.count) · aciertos \(correctCount)"; label.font = .systemFont(ofSize: 17, weight: .bold); label.textColor = .white; label.textAlignment = .center; label.backgroundColor = UIColor.systemPurple.withAlphaComponent(0.68); label.layer.cornerRadius = 14; label.clipsToBounds = true; label.heightAnchor.constraint(equalToConstant: 42).isActive = true; panel.addArrangedSubview(label) }
    private func showMenuArtwork(named name: String) { guard let url = Bundle.main.url(forResource: name, withExtension: "png", subdirectory: "MenuArtwork"), let image = UIImage(contentsOfFile: url.path) else { return }; menuArtwork.image = image; menuArtwork.isHidden = false; panel.isHidden = true; overlay.backgroundColor = .clear }
    private func addArtworkButton(label: String, x: CGFloat, y: CGFloat, width: CGFloat, height: CGFloat, tag: Int = 0, action: Selector) { let button = UIButton(type: .custom); button.translatesAutoresizingMaskIntoConstraints = false; button.tag = tag; button.accessibilityLabel = label; button.backgroundColor = .clear; button.addTarget(self, action: action, for: .touchUpInside); overlay.addSubview(button); NSLayoutConstraint.activate([NSLayoutConstraint(item: button, attribute: .leading, relatedBy: .equal, toItem: overlay, attribute: .trailing, multiplier: x, constant: 0), NSLayoutConstraint(item: button, attribute: .top, relatedBy: .equal, toItem: overlay, attribute: .bottom, multiplier: y, constant: 0), button.widthAnchor.constraint(equalTo: overlay.widthAnchor, multiplier: width), button.heightAnchor.constraint(equalTo: overlay.heightAnchor, multiplier: height)]); menuActionButtons.append(button) }
    @objc private func showStatistics() { clearPanel(); addTitle("Estadísticas clínicas", subtitle: "Aciertos por especialidad"); for (area, stat) in progress.subjectStats.sorted(by: { $0.key < $1.key }) { addFootnote("\(area): \(stat.correct)/\(stat.total) (\(stat.total == 0 ? 0 : stat.correct * 100 / stat.total)%)") }; addButton("Volver", action: #selector(showHomeAction)); overlay.isHidden = false }
    private func authenticateGameCenter() { GKLocalPlayer.local.authenticateHandler = { [weak self] controller, error in if let controller { self?.present(controller, animated: true) } else if let error { print("Game Center: \(error.localizedDescription)") } } }
    private func reportScore(_ score: Int, leaderboard: String) { GKLeaderboard.submitScore(score, context: 0, player: GKLocalPlayer.local, leaderboardIDs: [leaderboard]) { error in if let error { print("Leaderboard: \(error.localizedDescription)") } } }
}
